
-- Insert 16 new catalog items to reach 40 total

-- Communication domain: 1 more (already have 4 communication items, updating 1 to emotional_regulation, so need 2 more)
INSERT INTO public.life_skill_catalog (title, description, category, difficulty, age_group, estimated_duration_minutes, tags, is_active, sort_order, skill_domain, item_type, autism_skill_tags, clinical_reference, step_by_step_instructions, max_duration_minutes) VALUES
('Picture Exchange Practice', 'Practice communicating wants and needs using picture cards (PECS-inspired)', 'communication', 'beginner', '3-5', 10, ARRAY['pecs', 'aac', 'visual'], true, 25, 'communication', 'activity', ARRAY['requesting', 'aac', 'visual-communication', 'functional-communication'], 'PECS: Picture Exchange Communication System; ABA: Manding', '[{"step":1,"title":"Choose What You Want","description":"Look at the picture cards and find what you want"},{"step":2,"title":"Pick Up the Card","description":"Take the picture card off the board"},{"step":3,"title":"Give the Card","description":"Hand the card to your communication partner"},{"step":4,"title":"Wait","description":"Wait for your partner to say the word and give you the item"},{"step":5,"title":"Try Again","description":"Practice with 3 more items"}]'::jsonb, 10),

('Request Board Activity', 'Use a visual request board to practice making choices and expressing preferences', 'communication', 'beginner', '3-5', 10, ARRAY['choices', 'preferences', 'visual'], true, 26, 'communication', 'activity', ARRAY['choice-making', 'preference-expression', 'visual-supports'], 'TEACCH: Visual Supports; ABA: Preference Assessment', '[{"step":1,"title":"Look at Options","description":"Look at all the choices on your request board"},{"step":2,"title":"Point or Touch","description":"Point to what you want"},{"step":3,"title":"Say the Word","description":"Try to say the name of what you chose"},{"step":4,"title":"Receive Item","description":"Get the item you requested"},{"step":5,"title":"Say Thank You","description":"Practice saying thank you"}]'::jsonb, 10),

-- Sensory domain: 5 new items (only 1 existing)
('Sensory Bin Exploration', 'Explore different textures and materials in a sensory bin for tactile regulation', 'sensory', 'beginner', '3-5', 15, ARRAY['tactile', 'exploration', 'sensory'], true, 27, 'sensory', 'activity', ARRAY['tactile-processing', 'sensory-exploration', 'fine-motor'], 'OT: Sensory Integration; Ayres Sensory Integration', '[{"step":1,"title":"Choose a Bin","description":"Pick a sensory bin: rice, water beads, sand, or kinetic sand"},{"step":2,"title":"Touch Gently","description":"Put one hand in and feel the texture"},{"step":3,"title":"Describe It","description":"Tell how it feels: soft, rough, squishy, smooth?"},{"step":4,"title":"Use Tools","description":"Try scoops, cups, and funnels in the bin"},{"step":5,"title":"Clean Up","description":"Help sweep or wipe up any spills"}]'::jsonb, 15),

('Deep Pressure Activity', 'Use deep pressure techniques for calming and body awareness', 'sensory', 'beginner', '6-8', 10, ARRAY['deep-pressure', 'calming', 'proprioception'], true, 28, 'sensory', 'activity', ARRAY['proprioception', 'deep-pressure', 'body-awareness', 'calming'], 'OT: Wilbarger Deep Pressure Protocol; SI Theory', '[{"step":1,"title":"Choose Tool","description":"Pick: weighted blanket, body sock, or compression vest"},{"step":2,"title":"Get Comfortable","description":"Sit or lie down in a quiet space"},{"step":3,"title":"Apply Pressure","description":"Wrap up snugly or press firmly on arms and legs"},{"step":4,"title":"Breathe","description":"Take 10 slow deep breaths while feeling the pressure"},{"step":5,"title":"Rate How You Feel","description":"Do you feel calmer? Rate 1-5"}]'::jsonb, 10),

('Calm Down Corner Routine', 'Practice using a designated calm-down space with specific strategies', 'sensory', 'beginner', '3-5', 10, ARRAY['calm-down', 'self-regulation', 'safe-space'], true, 29, 'sensory', 'activity', ARRAY['self-regulation', 'safe-space', 'coping-skills', 'emotional-awareness'], 'Zones of Regulation; ABA: Replacement Behaviors', '[{"step":1,"title":"Go to Corner","description":"Walk to your calm-down corner when you feel upset"},{"step":2,"title":"Pick a Tool","description":"Choose: stuffed animal, fidget, or headphones"},{"step":3,"title":"Use Your Strategy","description":"Do deep breathing, squeeze the toy, or listen to music"},{"step":4,"title":"Wait","description":"Stay in the corner until you feel calmer (use timer)"},{"step":5,"title":"Check In","description":"Tell an adult how you feel now"}]'::jsonb, 10),

('Sound Sensitivity Training', 'Gradual exposure to sounds with coping strategies for auditory sensitivity', 'sensory', 'intermediate', '6-8', 15, ARRAY['auditory', 'desensitization', 'coping'], true, 30, 'sensory', 'activity', ARRAY['auditory-processing', 'desensitization', 'coping-strategies'], 'OT: Auditory Integration; CBT: Graduated Exposure', '[{"step":1,"title":"Rate Current Comfort","description":"How loud is too loud right now? Rate 1-5"},{"step":2,"title":"Start Quiet","description":"Listen to a gentle sound at low volume"},{"step":3,"title":"Slowly Increase","description":"Turn up volume one small step"},{"step":4,"title":"Use Coping Tool","description":"If uncomfortable, use headphones or deep breaths"},{"step":5,"title":"Record Progress","description":"Write down the highest comfortable level"}]'::jsonb, 15),

('Visual Sensory Activity', 'Explore visual stimulation with lights, colors, and patterns in a controlled way', 'sensory', 'beginner', '3-5', 10, ARRAY['visual', 'stimulation', 'exploration'], true, 31, 'sensory', 'activity', ARRAY['visual-processing', 'attention', 'sensory-exploration'], 'OT: Visual Perception; Sensory Integration Theory', '[{"step":1,"title":"Choose Activity","description":"Pick: lava lamp, light table, or color paddles"},{"step":2,"title":"Observe","description":"Watch the colors and patterns for 2 minutes"},{"step":3,"title":"Describe","description":"Tell what colors and shapes you see"},{"step":4,"title":"Create","description":"Make your own pattern with colored objects"},{"step":5,"title":"Draw What You Saw","description":"Draw your favorite pattern on paper"}]'::jsonb, 10),

-- Executive Function: 1 more
('Task Breakdown Practice', 'Learn to break big tasks into small manageable steps', 'cognitive', 'intermediate', '9-12', 15, ARRAY['planning', 'breaking-down', 'organization'], true, 32, 'executive_function', 'study', ARRAY['task-analysis', 'planning', 'organization', 'independence'], 'ABA: Task Analysis; TEACCH: Work Systems', '[{"step":1,"title":"Pick a Big Task","description":"Choose something that feels hard or overwhelming"},{"step":2,"title":"First Step","description":"What is the very first thing you need to do?"},{"step":3,"title":"Write Steps","description":"Write each small step on a separate sticky note"},{"step":4,"title":"Put in Order","description":"Arrange sticky notes from first to last"},{"step":5,"title":"Do Step 1","description":"Start with just the first step. Check it off!"},{"step":6,"title":"Continue","description":"Move to the next step when ready"}]'::jsonb, 15),

-- Daily Living: 1 more
('Table Setting Task', 'Practice setting a table correctly for meals', 'daily-living', 'beginner', '6-8', 10, ARRAY['table-setting', 'routine', 'independence'], true, 33, 'daily_living', 'chore', ARRAY['table-setting', 'sequencing', 'independence', 'following-directions'], 'ABA: Task Analysis; TEACCH: Visual Work Systems', '[{"step":1,"title":"Get a Placemat","description":"Put a placemat at each seat"},{"step":2,"title":"Plate","description":"Put a plate in the center of the placemat"},{"step":3,"title":"Fork","description":"Put a fork on the left side of the plate"},{"step":4,"title":"Knife and Spoon","description":"Put knife and spoon on the right side"},{"step":5,"title":"Cup","description":"Put a cup above the knife"},{"step":6,"title":"Napkin","description":"Fold a napkin and put it under the fork"}]'::jsonb, 10),

-- Emotional Regulation: 1 more (already have 4+1 moved from communication)
('Breathing Exercise Game', 'Fun breathing exercises disguised as games for emotional regulation', 'emotional', 'beginner', '3-5', 8, ARRAY['breathing', 'calming', 'game'], true, 34, 'emotional_regulation', 'game', ARRAY['breathing', 'self-regulation', 'calming', 'body-awareness'], 'CBT: Relaxation Training; Zones of Regulation', '[{"step":1,"title":"Smell the Flower","description":"Breathe in slowly through your nose like smelling a flower"},{"step":2,"title":"Blow the Candle","description":"Breathe out slowly like blowing out a birthday candle"},{"step":3,"title":"Balloon Belly","description":"Put hands on tummy, breathe in to make belly big like a balloon"},{"step":4,"title":"Let Air Out","description":"Slowly let the air out, feel belly get small"},{"step":5,"title":"Count Breaths","description":"Do 5 more breaths, count each one on your fingers"}]'::jsonb, 8),

-- Academic Readiness: 5 new items
('Letter Tracing Adventure', 'Trace and practice writing letters with visual guides', 'academic', 'beginner', '3-5', 15, ARRAY['letters', 'writing', 'tracing'], true, 35, 'academic', 'study', ARRAY['letter-recognition', 'handwriting', 'visual-motor', 'pre-writing'], 'TEACCH: Structured Teaching; Handwriting Without Tears', '[{"step":1,"title":"Choose a Letter","description":"Pick a letter card to practice"},{"step":2,"title":"Trace with Finger","description":"Trace the letter with your finger 3 times"},{"step":3,"title":"Trace with Pencil","description":"Trace over the dotted letter with a pencil"},{"step":4,"title":"Write It","description":"Try writing the letter on your own"},{"step":5,"title":"Find It","description":"Find that letter in a book or on a poster"},{"step":6,"title":"Say the Sound","description":"Say the sound the letter makes"}]'::jsonb, 15),

('Number Matching Game', 'Match numbers to quantities using hands-on manipulatives', 'academic', 'beginner', '3-5', 12, ARRAY['numbers', 'counting', 'matching'], true, 36, 'academic', 'game', ARRAY['number-recognition', 'counting', 'one-to-one-correspondence', 'math-readiness'], 'ABA: Discrete Trial; TEACCH: Structured Teaching', '[{"step":1,"title":"Lay Out Number Cards","description":"Put number cards 1-10 in a row"},{"step":2,"title":"Count Objects","description":"Count out the right number of objects for each card"},{"step":3,"title":"Match Them","description":"Place objects next to their matching number"},{"step":4,"title":"Check Your Work","description":"Point and count each group to make sure"},{"step":5,"title":"Mix and Try Again","description":"Mix everything up and do it again faster"}]'::jsonb, 12),

('Color Sorting Challenge', 'Sort objects by color to build categorization and cognitive skills', 'academic', 'beginner', '3-5', 10, ARRAY['colors', 'sorting', 'categories'], true, 37, 'academic', 'game', ARRAY['color-recognition', 'categorization', 'visual-discrimination', 'cognitive-skills'], 'ABA: Matching-to-Sample; TEACCH: Visual Organization', '[{"step":1,"title":"Set Up Containers","description":"Put out colored containers or mats"},{"step":2,"title":"Look at Objects","description":"Look at the pile of colorful objects"},{"step":3,"title":"Sort by Color","description":"Put each object in the matching color container"},{"step":4,"title":"Name Colors","description":"Say the name of each color as you sort"},{"step":5,"title":"Count Groups","description":"Count how many objects are in each color group"}]'::jsonb, 10),

('Pattern Recognition Quest', 'Find and create patterns using colors, shapes, and objects', 'academic', 'intermediate', '6-8', 15, ARRAY['patterns', 'logic', 'sequencing'], true, 38, 'academic', 'game', ARRAY['pattern-recognition', 'logical-thinking', 'sequencing', 'prediction'], 'ABA: Conditional Discrimination; TEACCH: Cognitive Development', '[{"step":1,"title":"Look at the Pattern","description":"Study the pattern of colors or shapes"},{"step":2,"title":"What Comes Next?","description":"Predict the next item in the pattern"},{"step":3,"title":"Check","description":"Flip the card to see if you''re right"},{"step":4,"title":"Make Your Own","description":"Create a pattern for someone else to solve"},{"step":5,"title":"Try Harder Patterns","description":"Move to AB-AB, then ABC-ABC patterns"}]'::jsonb, 15),

('Shape and Size Sorting', 'Sort and compare shapes and sizes to build spatial reasoning', 'academic', 'beginner', '3-5', 10, ARRAY['shapes', 'sizes', 'spatial'], true, 39, 'academic', 'study', ARRAY['shape-recognition', 'size-comparison', 'spatial-reasoning', 'classification'], 'TEACCH: Visual-Spatial Skills; ABA: Feature/Function/Class', '[{"step":1,"title":"Name the Shapes","description":"Look at each shape and say its name"},{"step":2,"title":"Sort by Shape","description":"Group all circles, squares, triangles together"},{"step":3,"title":"Sort by Size","description":"Put shapes from smallest to biggest"},{"step":4,"title":"Find Shapes","description":"Look around the room - find 3 circles, 3 squares"},{"step":5,"title":"Draw Shapes","description":"Draw each shape and color them your favorite colors"}]'::jsonb, 10),

-- Social: 1 more
('Emotion Charades', 'Act out and guess emotions to build emotional literacy and social awareness', 'social', 'intermediate', '6-8', 15, ARRAY['emotions', 'acting', 'social'], true, 40, 'social', 'game', ARRAY['emotional-literacy', 'body-language', 'perspective-taking', 'social-awareness'], 'ABA: Social Cognition; ESDM: Emotional Understanding; Social Thinking', '[{"step":1,"title":"Draw an Emotion Card","description":"Pick a card with an emotion written on it"},{"step":2,"title":"Act It Out","description":"Show the emotion with your face and body - no words!"},{"step":3,"title":"Others Guess","description":"Let your friends or family guess the emotion"},{"step":4,"title":"Discuss","description":"Talk about when you might feel that way"},{"step":5,"title":"Switch","description":"Let someone else pick a card and act it out"}]'::jsonb, 15);
